SELECT i.assignee_id, u.display_name AS assignee_name, COUNT(*) AS total, COUNT(*) FILTER (WHERE i.status_id IN
#{sid}
) AS done_count FROM issue i LEFT JOIN sys_user u ON u.id = i.assignee_id WHERE i.deleted_at IS NULL
GROUP BY i.assignee_id, u.display_name ORDER BY total DESC

SELECT COUNT(*) AS total,
       COUNT(*) FILTER (WHERE i.status_id NOT IN

               #{sid}

       ) AS open_count,
       COUNT(*) FILTER (WHERE i.status_id IN

               #{sid}

       ) AS closed_count,
       COUNT(*) FILTER (WHERE i.assignee_id IS NULL) AS unassigned,
       COUNT(*) FILTER (WHERE i.due_date IS NOT NULL
           AND i.due_date < CAST(#{now} AS DATE)
           AND i.status_id NOT IN

               #{sid}

       ) AS overdue
FROM issue i
WHERE i.deleted_at IS NULL

SELECT p.id AS project_id,
       p.name AS project_name,
       p.key AS project_key,
       COUNT(*) AS total,
       COUNT(*) FILTER (WHERE i.status_id NOT IN

               #{sid}

       ) AS open_count,
       COUNT(*) FILTER (WHERE i.status_id IN

               #{sid}

       ) AS closed_count,
       COUNT(*) FILTER (WHERE i.due_date IS NOT NULL
           AND i.due_date < CAST(#{now} AS DATE)
           AND i.status_id NOT IN

               #{sid}

       ) AS overdue
FROM issue i
JOIN project p ON p.id = i.project_id
WHERE i.deleted_at IS NULL



            AND i.project_id = #{projectIds[0]}


            AND i.project_id IN

                #{pid}




        AND 1=0



GROUP BY p.id, p.name, p.key
ORDER BY total DESC

SELECT i.id AS issue_id, i.issue_key, i.title, p.name AS project_name, s.name AS status_name, COALESCE(SUM(t.duration), 0) AS total_minutes, COUNT(t.id) AS entry_count FROM time_entry t JOIN issue i ON i.id = t.issue_id JOIN project p ON p.id = t.project_id LEFT JOIN issue_status s ON s.id = i.status_id WHERE t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date AND i.deleted_at IS NULL
AND t.project_id IN #{pid}
AND 1=0
GROUP BY i.id, i.issue_key, i.title, p.name, s.name ORDER BY total_minutes DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT t.issue_id) FROM time_entry t JOIN issue i ON i.id = t.issue_id WHERE t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date AND i.deleted_at IS NULL
AND t.project_id IN #{pid}
AND 1=0

SELECT t.id AS entry_id, t.work_date::text AS work_date, u.display_name AS user_name, i.issue_key, i.title AS issue_title, p.name AS project_name, COALESCE(wiav.name, '未分类') AS work_type, COALESCE(t.duration, 0) AS minutes, t.description FROM time_entry t JOIN sys_user u ON u.id = t.user_id JOIN issue i ON i.id = t.issue_id JOIN project p ON p.id = t.project_id LEFT JOIN time_entry_attribute_value teav ON teav.time_entry_id = t.id AND teav.attribute_id = #{workTypeAttributeId} LEFT JOIN work_item_attribute_value wiav ON wiav.id = teav.value_id WHERE t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date AND i.deleted_at IS NULL
AND t.project_id IN #{pid}
AND 1=0
ORDER BY t.work_date DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(t.id) FROM time_entry t JOIN issue i ON i.id = t.issue_id WHERE t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date AND i.deleted_at IS NULL
AND t.project_id IN #{pid}
AND 1=0

SELECT COUNT(DISTINCT t.user_id) FROM time_entry t JOIN issue i ON i.id = t.issue_id WHERE t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date AND i.deleted_at IS NULL
AND t.project_id IN #{pid}
AND 1=0

SELECT i.id AS issue_id, i.issue_key, i.title, p.name AS project_name, COALESCE(u.display_name, '未分配') AS assignee_name, i.estimated_hours, i.spent_hours FROM issue i JOIN project p ON p.id = i.project_id LEFT JOIN sys_user u ON u.id = i.assignee_id WHERE i.deleted_at IS NULL AND i.estimated_hours IS NOT NULL AND i.estimated_hours > 0
AND i.project_id IN #{pid}
AND 1=0
ORDER BY (COALESCE(i.spent_hours, 0) / i.estimated_hours) DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM issue i WHERE i.deleted_at IS NULL AND i.estimated_hours IS NOT NULL AND i.estimated_hours > 0
AND i.project_id IN #{pid}
AND 1=0

WITH transitions AS ( SELECT a.old_value, a.new_value, EXTRACT(EPOCH FROM ( COALESCE( LEAD(a.created_at) OVER (PARTITION BY a.issue_id ORDER BY a.created_at), NOW() ) - a.created_at )) / 3600.0 AS duration_hours FROM issue_activity a JOIN issue i ON i.id = a.issue_id WHERE a.action = 'change_status' AND a.field_name = 'status' AND a.created_at BETWEEN #{start} AND #{end}
AND i.project_id IN #{pid}
AND i.id IN #{iid}
) SELECT COALESCE(old_value, '(无)') AS from_status, COALESCE(new_value, '(无)') AS to_status, COUNT(*) AS transition_count, AVG(duration_hours) AS avg_duration_hours FROM transitions GROUP BY old_value, new_value ORDER BY transition_count DESC LIMIT 50

SELECT CAST(a.created_at AS DATE) AS day, COUNT(*) AS cnt FROM issue_activity a JOIN issue i ON i.id = a.issue_id WHERE a.field_name = 'status' AND a.action IN ('status_changed', 'update') AND a.created_at >= #{startDate} AND a.created_at <= #{endDate} AND a.new_value IN #{name}
AND i.project_id IN #{pid}
AND i.id IN #{iid}
AND i.deleted_at IS NULL GROUP BY CAST(a.created_at AS DATE) ORDER BY day

SELECT CAST(a.created_at AS DATE) AS day,
       COUNT(*) AS cnt
FROM issue_activity a
JOIN issue i ON i.id = a.issue_id
WHERE a.field_name = 'status'
  AND a.action IN ('status_changed', 'update')
  AND a.created_at >= #{startDate}
  AND a.created_at <= #{endDate}
  AND a.old_value IN
  #{name}
  AND a.new_value IN
  #{name}

    AND i.project_id IN
    #{pid}


    AND i.id IN
    #{iid}

  AND i.deleted_at IS NULL
GROUP BY CAST(a.created_at AS DATE)
ORDER BY day

SELECT CAST(a.created_at AS DATE) AS day, COUNT(*) AS cnt FROM issue_activity a JOIN issue i ON i.id = a.issue_id WHERE a.field_name = 'status' AND a.action IN ('status_changed', 'update') AND a.created_at >= #{startDate} AND a.created_at <= #{endDate} AND a.new_value IN #{name}
AND i.project_id IN #{pid}
AND i.id IN #{iid}
AND i.deleted_at IS NULL GROUP BY CAST(a.created_at AS DATE) ORDER BY day

WITH -- 所有进入跟踪状态的事件 enter_events AS ( SELECT a.issue_id, a.created_at AS entered_at, ROW_NUMBER() OVER (PARTITION BY a.issue_id ORDER BY a.created_at) AS rn FROM issue_activity a JOIN issue i ON i.id = a.issue_id WHERE a.field_name = 'status' AND a.new_value IN #{s}
AND i.project_id IN #{pid}
AND i.id IN #{iid}
AND i.deleted_at IS NULL ), -- 所有离开跟踪状态的事件 exit_events AS ( SELECT a.issue_id, a.created_at AS exited_at, ROW_NUMBER() OVER (PARTITION BY a.issue_id ORDER BY a.created_at) AS rn FROM issue_activity a JOIN issue i ON i.id = a.issue_id WHERE a.field_name = 'status' AND a.old_value IN #{s}
AND i.project_id IN #{pid}
AND i.id IN #{iid}
AND i.deleted_at IS NULL ), -- 配对：每个进入事件匹配最近的离开事件 paired AS ( SELECT e.issue_id, e.entered_at, x.exited_at, COALESCE(x.exited_at, NOW()) AS effective_exit, EXTRACT(EPOCH FROM (COALESCE(x.exited_at, NOW()) - e.entered_at)) / 3600.0 AS age_hours, CASE WHEN x.exited_at IS NOT NULL THEN TRUE ELSE FALSE END AS has_exited FROM enter_events e LEFT JOIN exit_events x ON x.issue_id = e.issue_id AND x.rn = e.rn ), -- 按时间粒度分组 bucketed AS ( SELECT
TO_CHAR(DATE_TRUNC('week', COALESCE(exited_at, effective_exit)), 'YYYY-MM-DD') AS period
TO_CHAR(DATE_TRUNC('month', COALESCE(exited_at, effective_exit)), 'YYYY-MM') AS period
CAST(CAST(COALESCE(exited_at, effective_exit) AS DATE) AS VARCHAR) AS period
, age_hours, has_exited FROM paired WHERE COALESCE(exited_at, effective_exit) >= #{startDate} AND COALESCE(exited_at, effective_exit) <= #{endDate} ) SELECT period, AVG(age_hours) AS avg_age_hours, COUNT(*) FILTER (WHERE has_exited = TRUE) AS outflow_count, COUNT(*) FILTER (WHERE has_exited = FALSE) AS staying_count FROM bucketed GROUP BY period ORDER BY period
